program='''from collections import Counter

def _bands(lines):
    bands = []
    start = None
    for i, line in enumerate(lines):
        active = any(v != 0 for v in line)
        if active and start is None:
            start = i
        elif not active and start is not None:
            bands.append((start, i))
            start = None
    if start is not None:
        bands.append((start, len(lines)))
    return bands

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    background = counts.most_common(1)[0][0]
    rb = _bands(grid)
    cb = _bands([[grid[r][c] for r in range(h)] for c in range(w)])
    labels = []
    for r0, r1 in rb:
        rowlabels = []
        for c0, c1 in cb:
            freq = Counter(v for row in grid[r0:r1] for v in row[c0:c1] if v not in (0, background))
            rowlabels.append(freq.most_common(1)[0][0] if freq else None)
        labels.append(rowlabels)
    out = [row[:] for row in grid]
    # Join equal markers across zero gutters, keeping their footprint within the marker's rows/columns.
    for ri, (r0, r1) in enumerate(rb):
        for a in range(len(cb)):
            ca = labels[ri][a]
            if ca is None:
                continue
            for b in range(a + 1, len(cb)):
                if labels[ri][b] != ca:
                    continue
                for y in range(r0, r1):
                    if any(grid[y][x] == ca for x in range(cb[a][0], cb[a][1])):
                        for k in range(a, b):
                            for x in range(cb[k][1], cb[k+1][0]):
                                if out[y][x] == 0:
                                    out[y][x] = ca
    for ci, (c0, c1) in enumerate(cb):
        for a in range(len(rb)):
            ca = labels[a][ci]
            if ca is None:
                continue
            for b in range(a + 1, len(rb)):
                if labels[b][ci] != ca:
                    continue
                for x in range(c0, c1):
                    if any(grid[y][x] == ca for y in range(rb[a][0], rb[a][1])):
                        for k in range(a, b):
                            for y in range(rb[k][1], rb[k+1][0]):
                                if out[y][x] == 0:
                                    out[y][x] = ca
    return out
'''
